import type { Metadata } from "next";
import { site } from "@/lib/site";

export const defaultTitle = `${site.name} — ${site.role}`;

/** The share card generated by src/app/opengraph-image.tsx. */
const shareCard = {
  url: "/opengraph-image",
  type: "image/png",
  width: 1200,
  height: 630,
  alt: defaultTitle,
};

interface PageSeo {
  /** Page title; the root layout's template appends the site name. Omit on the homepage. */
  title?: string;
  description?: string | null;
  /** Canonical path, also used for og:url, e.g. "/projects". */
  path: string;
  /** Share image. Defaults to the generated card. */
  image?: string | null;
  imageAlt?: string;
  type?: "website" | "article";
}

/**
 * The complete set of search and share tags for one page.
 *
 * Next replaces nested objects such as `openGraph` per route segment instead
 * of merging them, so a page that sets only part of `openGraph` loses the
 * layout's image and site name. Every page sets all of its tags here instead.
 */
export function pageMetadata({
  title,
  description,
  path,
  image,
  imageAlt,
  type = "website",
}: PageSeo): Metadata {
  const fullTitle = title ? `${title} — ${site.name}` : defaultTitle;
  const desc = description || site.description;
  const images = [image ? { url: image, alt: imageAlt ?? fullTitle } : shareCard];

  return {
    ...(title ? { title } : {}),
    description: desc,
    alternates: { canonical: path },
    openGraph: {
      type,
      url: path,
      siteName: site.name,
      locale: "en_US",
      title: fullTitle,
      description: desc,
      images,
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description: desc,
      images,
    },
  };
}
